\copy (select s.annee_debut, s.joueur_id, s.equipe_id, j.nom, s.matchs_joues, s.entrees_en_jeu, s.minutes, coalesce(s.homme_du_match,0) motm, coalesce(s.buts,0) buts, coalesce(s.passes_decisives,0) ast, coalesce(s.tirs_cadres,0) sot, coalesce(s.tirs,0) tirs, coalesce(s.tacles_reussis,0) tkl, coalesce(s.interceptions,0) intc, coalesce(s.degagements,0) clr, coalesce(s.contres,0) blk, coalesce(s.duels_aeriens_gagnes,0) aer, coalesce(s.passes,0) passes, coalesce(s.passes_courtes_reussies,0)+coalesce(s.passes_longues_reussies,0) passes_ok, coalesce(s.passes_cles,0) kp, coalesce(s.dribbles_reussis,0) drb, coalesce(s.arrets,0) saves, coalesce(s.fautes_commises,0) fouls, coalesce(s.cartons_jaunes,0) yc, coalesce(s.cartons_rouges,0) rc, coalesce(s.buts_contre_son_camp,0) og, coalesce(s.pertes_de_balle,0) turn, s.note_moyenne, s.postes_occupes, j.poste poste_note, p.tour_elimination, p.vainqueur, e.nom equipe from stats_joueur_saison s join joueur j using(joueur_id) join equipe e using(equipe_id) join parcours_equipe_saison p using(annee_debut,equipe_id)) to stdout with csv header
